1	/**
2	 * Progressive Select All ladder (progressive-select-all change, design.md
3	 * D1-D5): repeated Mod-A climbs node's own content -> node's whole subtree
4	 * -> its siblings' combined run -> the parent's whole subtree -> repeat
5	 * outward -> the whole outline body, then falls through to native Select
6	 * All for the whole document. Stateless: every call recomputes the ladder
7	 * from the document tree and the CURRENT selection, with no press-count or
8	 * "last rung" state stored anywhere.
9	 *
10	 * The "siblings' combined run" step (real-vault experiment, added after the
11	 * first manual pass) sits between a node's own subtree and its parent's:
12	 * select this node -> select it plus all its siblings at the same level
13	 * (NOT the parent's own line) -> select the parent's whole subtree (the
14	 * parent's own line included). At the top level, "siblings' combined run"
15	 * already IS the whole outline body, so the ladder's dedup step collapses
16	 * the two into one rung there — no separate case needed.
17	 *
18	 * Pure module — no CodeMirror imports; src/plugin/keymap.ts is the CM6
19	 * adapter (converts to/from character offsets, decides per-range fallback
20	 * to native Select All). Reuses escalate.ts's `subtreeCoverOf`/`Cover`
21	 * rather than recomputing subtree geometry — this module only adds the
22	 * rung *sequence* and the *next-rung* comparison escalate.ts has no need
23	 * for (its own job is escalating a transaction's shape, not climbing a
24	 * ladder across repeated identical keypresses).
25	 */
26	
27	import type { OutlineDoc, OutlineNode, NodePath } from './model';
28	import { findPath, nodeAt } from './model';
29	import { nodeAtLine, nodeStartLine } from './locate';
30	import { contentColumnCh } from './ops';
31	import { subtreeCoverOf, type Cover, type LinePos, type LineRange } from './escalate';
32	
33	function posBefore(a: LinePos, b: LinePos): boolean {
34	  return a.line < b.line || (a.line === b.line && a.ch < b.ch);
35	}
36	
37	function posEqual(a: LinePos, b: LinePos): boolean {
38	  return a.line === b.line && a.ch === b.ch;
39	}
40	
41	function isBackward(range: LineRange): boolean {
42	  return posBefore(range.head, range.anchor);
43	}
44	
45	function coverEqual(a: Cover, b: Cover): boolean {
46	  return posEqual(a.start, b.start) && posEqual(a.end, b.end);
47	}
48	
49	/** `cover` contains the bounds `[lo, hi]` (both inclusive-endpoint
50	 * comparisons — a cover whose start/end exactly equals `lo`/`hi` counts as
51	 * containing it). */
52	function containsBounds(cover: Cover, lo: LinePos, hi: LinePos): boolean {
53	  return !posBefore(lo, cover.start) && !posBefore(cover.end, hi);
54	}
55	
56	/**
57	 * A node's own content cover (rung 1): its own lines only, excluding
58	 * descendants and its trailing gap. A list item's cover starts after its
59	 * marker (`contentColumnCh`, the same boundary `splitNode` uses) — headings and
60	 * paragraphs have no marker to exclude (design.md D4), so their content
61	 * starts at column 0 of their first line.
62	 *
63	 * NOT `./caret.ts`'s `contentBoundaryCh`, which deliberately answers a
64	 * different question: it leaves an ATX prefix inside a list item addressable and
65	 * covers a marker with no trailing space. The two agree on ordinary items and
66	 * differ on `- # title` and a bare `-`; this ladder keeps `contentColumnCh`'s
67	 * semantics, unchanged by the caret work.
68	 */
69	function ownContentCover(doc: OutlineDoc, node: OutlineNode): Cover {
70	  const start = nodeStartLine(doc, node.id);
71	  const firstLine = node.lines[0] ?? '';
72	  const startCh = node.kind === 'list-item' ? contentColumnCh(firstLine) : 0;
73	  const lastLine = node.lines[node.lines.length - 1] ?? '';
74	  return {
75	    start: { line: start, ch: startCh },
76	    end: { line: start + node.lines.length - 1, ch: lastLine.length },
77	  };
78	}
79	
80	function childrenAtScope(doc: OutlineDoc, scopePath: NodePath): readonly OutlineNode[] {
81	  let list: readonly OutlineNode[] = doc.children;
82	  for (const index of scopePath) list = list[index]!.children;
83	  return list;
84	}
85	
86	/** The combined cover of every node in `siblings` (a non-empty sibling
87	 * list at one scope) — first sibling's subtree start through last
88	 * sibling's subtree end. At the top level this is the whole outline body;
89	 * at any other level it's "this node plus all its siblings," the parent's
90	 * own line NOT included. */
91	function siblingsRunCover(doc: OutlineDoc, siblings: readonly OutlineNode[]): Cover {
92	  const first = siblings[0]!;
93	  const last = siblings[siblings.length - 1]!;
94	  return { start: subtreeCoverOf(doc, first).start, end: subtreeCoverOf(doc, last).end };
95	}
96	
97	/**
98	 * The ordered ladder of rungs for `node`, smallest first: own content, then
99	 * — at `node`'s own level, then each ancestor's level outward — that
100	 * level's own subtree followed by that level's siblings' combined run,
101	 * ending at the whole outline body. Consecutive equal covers (a leaf
102	 * node's content and subtree coincide; a lone top-level node's subtree
103	 * equals its own siblings' run, which is the whole outline body) collapse
104	 * to one rung, so the next-rung search below never needs to special-case a
105	 * zero-growth step.
106	 */
107	function ladderFor(doc: OutlineDoc, node: OutlineNode): readonly Cover[] {
108	  const path = findPath(doc, node.id);
109	  if (!path) return [];
110	
111	  const covers: Cover[] = [ownContentCover(doc, node)];
112	  for (let len = path.length; len >= 1; len--) {
113	    const levelNode = nodeAt(doc, path.slice(0, len));
114	    if (!levelNode) continue;
115	    covers.push(subtreeCoverOf(doc, levelNode));
116	    const siblings = childrenAtScope(doc, path.slice(0, len - 1));
117	    if (siblings.length > 0) covers.push(siblingsRunCover(doc, siblings));
118	  }
119	
120	  const deduped: Cover[] = [];
121	  for (const cover of covers) {
122	    if (deduped.length === 0 || !coverEqual(deduped[deduped.length - 1]!, cover)) {
123	      deduped.push(cover);
124	    }
125	  }
126	  return deduped;
127	}
128	
129	/**
130	 * The next rung up the ladder for one selection range (design.md D3):
131	 * recomputed from the CURRENT range and the document tree, no stored
132	 * state. The node context is resolved from the range's `anchor`. Returns
133	 * the smallest rung that both contains the range and differs from it —
134	 * ladder rungs nest monotonically by construction, so once a rung exactly
135	 * matches the range, every later rung also contains it and the search can
136	 * simply continue past the match rather than special-casing it.
137	 *
138	 * Returns `null` when there is no further node-shaped rung to climb to:
139	 * the range already equals the ladder's top rung (whole outline body), or
140	 * the anchor isn't inside any node's jurisdiction at all (e.g. resting in
141	 * the preamble, or past the document's very final trailing gap) — in both
142	 * cases the caller should let native Select All run for this range.
143	 */
144	export function nextRung(doc: OutlineDoc, range: LineRange): LineRange | null {
145	  const node = nodeAtLine(doc, range.anchor.line);
146	  if (!node) return null;
147	
148	  const lo = isBackward(range) ? range.head : range.anchor;
149	  const hi = isBackward(range) ? range.anchor : range.head;
150	
151	  for (const cover of ladderFor(doc, node)) {
152	    if (!containsBounds(cover, lo, hi)) continue;
153	    if (posEqual(cover.start, lo) && posEqual(cover.end, hi)) continue; // already here — keep climbing
154	    return isBackward(range)
155	      ? { anchor: cover.end, head: cover.start }
156	      : { anchor: cover.start, head: cover.end };
157	  }
158	  return null;
159	}
160	
161	/**
162	 * Multi-range entry point (design.md D5): each range climbs its own ladder
163	 * independently — there is no uniform/forced-common-rung step here, unlike
164	 * `escalateRanges`' multi-range rule. Returns one entry per input range,
165	 * `null` where that range has no further rung (see `nextRung`); the CM6
166	 * adapter decides what `null` means for dispatch (leave that range as-is,
167	 * or — when every range is `null` — fall through to native Select All
168	 * entirely).
169	 */
170	export function nextRungs(doc: OutlineDoc, ranges: readonly LineRange[]): readonly (LineRange | null)[] {
171	  return ranges.map((range) => nextRung(doc, range));
172	}
