import { describe, it } from 'node:test';
import assert from 'node:assert/strict';
import { parseOutline } from '../../../../src/parse';
import { forestCoverOf, subtreeCoverOf } from '../../../../src/escalate';
import { nodeAtLine } from '../../../../src/locate';

/** Probe: does the cover's END edge identify the anchor node for an UPWARD
 * extension, the way design D3 claims? */
describe('D3 backward-anchor probe', () => {
  const text = ['- P', '\t- c1', '\t- c2'].join('\n');
  const doc = parseOutline(text);

  it('reports the sequence for anchor c1 going up', () => {
    const c1 = nodeAtLine(doc, 1)!;
    assert.equal(c1.lines[0], '\t- c1');

    // element 0 — the anchor's own subtree
    const e0 = subtreeCoverOf(doc, c1);
    console.log('e0 (c1 subtree):', JSON.stringify(e0));

    // element 1 — additionally take the previous node in content order (P)
    const prev = nodeAtLine(doc, e0.start.line - 1)!;
    console.log('prev node lines:', JSON.stringify(prev.lines));
    const e1 = forestCoverOf(doc, c1, prev);
    console.log('e1:', JSON.stringify(e1.cover));
    console.log('e1 roots:', e1.roots.map((r) => r.node.lines[0]));

    // Now reverse: which node does the cover's END edge resolve to?
    const recovered = nodeAtLine(doc, e1.cover.end.line)!;
    console.log('anchor recovered from end edge:', JSON.stringify(recovered.lines));
    assert.equal(recovered.lines[0], '\t- c1', 'end edge should identify c1');
  });
});

