describe('extendSelection: symmetry and shrinking', () => {
  const flat = parse(['Alpha one.', '', 'Bravo two.', '', 'Charlie three.'].join('\n'));

  it('Shift+Up undoes Shift+Down (examples E5)', () => {
    expect(press(flat, caret(2, 3), ['down', 'down', 'up'])).toEqual([
